import{_ as o,p as a,q as r,s as t,R as d,t as p,Y as I,n}from"./framework-e1bed10d.js";const c={},u=t("h1",{id:"ai-时代-程序员为什么要更懂商业逻辑",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#ai-时代-程序员为什么要更懂商业逻辑","aria-hidden":"true"},"#"),d(" AI 时代，程序员为什么要更懂商业逻辑")],-1),A={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247484137&idx=1&sn=b10e2dee27a7bc4ff050830dc6bbb2af&chksm=e8c6f295dfb17b8354928212d2ac7ff18b310d58b87235b49f212e8423daa2378b1caa53cd4c",target:"_blank",rel:"noopener noreferrer"},s=I('<hr><h2 id="ai时代-程序员为什么要更懂商业逻辑" tabindex="-1"><a class="header-anchor" href="#ai时代-程序员为什么要更懂商业逻辑" aria-hidden="true">#</a> AI时代，程序员为什么要更懂商业逻辑</h2><p>自序里，我讲了这二十年是怎么从工行的柜面，一路走到产业金融的，也讲了同一个信贷业务，为什么会在一家行和另一家行里，长出完全不同的系统。那是过去的路。这篇前言，想说说当下和往后的事，AI 时代，程序员到底该守住什么。</p><p>你有没有过这样的经历？想做个小生意，拿计算器算了半天账，还是拿不准这个买卖到底赚不赚钱；或者在网上看到一个产品，功能看着挺全，真用起来才发现处处别扭，根本解决不了你要解决的问题。这些感受背后，其实是同一个道理：光把功能做出来没用，关键是得搞清楚这东西到底为什么做、解决什么问题。这个道理，放在做软件上成立，放在开公司上成立，放在我们每个人选职业、做决策上，同样成立。</p><p>AI 把编程的门槛踩得很低，编程本身越来越不值钱。但程序员的价值没丢，只是换了个地方。</p><p>以前，会写代码是门手艺，靠它吃饭。现在，AI 几句话就能把代码写出来，比手敲还快，不懂编程的人也能拿它做个小程序。那程序员还剩什么？我说，剩两样东西凑在一块：懂商业逻辑，加上懂技术细节、会做架构。</p><p>不光是程序员，这两年你肯定也感觉到了：以前要找设计师做张海报、找文案写篇文章、找会计做个报表，现在打开AI，说几句话就能出个八九不离十的初稿。那些&quot;会操作工具&quot;的本事，正在变得越来越不值钱。但你有没有发现，同样用AI，有人做出来的东西真能用，有人做出来的东西看着像那么回事，一上手全是错？差别不在工具用得熟不熟，在于用的人知不知道自己要做什么、为什么这么做、错在哪。这个&quot;知道为什么&quot;的能力，就是不管什么行业、什么岗位，AI时代最值钱的本事。</p><p>先说为什么非得懂商业逻辑。</p><p>一个系统，从来不是&quot;代码写出来&quot;就完事。写代码只是其中很小一段，更重的活儿在前面：业务在什么场景下提需求，要解决什么问题，怎么用信息化把整条流程管起来。这些场景背后的业务流程和规则，就是我常讲的商业逻辑。</p><p>实现一个程序不难，AI 就干得了。可要完成一个商业闭环的设计，是另一回事，你得搞清楚这事到底在解决什么问题，为什么这么做，会踩什么坑。这些细节往往决定系统关键流程往哪走，也直接关系操作风险。</p><p>不懂这些，会写出什么样的系统？轻则返工，重则上不了线；碰上监管严的行业，可能直接被叫停；涉及钱款的，一个规则没吃透，就是一笔坏账。</p><p>再加上 AI 时代的新问题：大模型会一本正经地胡说八道。它写的代码跑得通，业务逻辑却可能是错的，而且错得很自信。你要是不懂业务，根本看不出来它错在哪。这时候，懂业务逻辑就不是加分项，是保命的本事。</p><p>我举个你身边的例子。你用AI帮你写过请假条吧？它写得挺通顺，但领导看完可能还是会问你：你这个假为什么要请？怎么跟手头的工作交接？这个月的考勤怎么算？这些问题，AI答不上来，因为它不知道你这家公司的规矩，也不知道你这个岗位的特殊性。做软件也是一样：AI能把代码写出来，但它不知道这家银行的客户有什么特点、监管有什么要求、之前出过什么事故、什么地方绝对不能碰。这些东西，就是&quot;商业逻辑&quot;，是AI拿不走的。</p><p>那懂技术细节、有架构设计能力，又好在哪？好在能把两件事做好：总成本低，非黑盒。</p><p>先说总成本。真正便宜的系统，是架构设计对的系统。业务往哪走、模块怎么切、数据怎么管、以后怎么改，动手前想明白，才不会反复返工，不会堆出一片不敢动的技术债。不懂业务的人拿 AI 写代码，写一个是一个，改一处牵全身，看着快，其实贵。</p><p>再说非黑盒。不少人用 AI 写系统，写出来的东西自己也不懂，能跑但不知道为什么这么跑，出了问题也不知道从哪查。非黑盒，就是系统的每一层都看得懂、查得清、改得起。程序员懂技术细节，就能守住系统的底：每个关键环节自己看得懂，出了事能一层层查下去。这样的系统才可控，才敢迭代。</p><p>这本书的主体读者，是程序员和架构师，尤其是在金融信贷行业做系统的技术人。但我也发现，越来越多非技术角色在找这类书：业务员想搞懂系统怎么帮自己获客，产品经理想搞懂技术边界在哪，风控想搞懂模型怎么落地，CTO、CIO 想搞懂 AI 时代的技术投资和转型节奏。所以我把信贷产业链上六类角色的处境摊开说，你可以对照自己的位置看，但书的主线，始终是技术人的视角。</p><table><thead><tr><th>角色</th><th>AI 时代的核心挑战</th><th>为什么必须懂商业逻辑+ 技术细节</th><th>本书对应内容</th></tr></thead><tbody><tr><td>业务员</td><td>AI 能自动获客、生成话术、智能跟进，但客户信任和复杂需求判断 AI 做不了</td><td>不懂业务流程，给客户讲不清产品、算不对额度；不懂系统，不知道工具能帮自己做什么、客户数据从哪来</td><td>第一~三章、第十二章：业务流程、合规、获客实践</td></tr><tr><td>产品经理</td><td>AI 能生成需求文档和原型，但业务洞察和取舍判断 AI 做不了</td><td>不懂技术边界，会做出&quot;看起来好、做不出来&quot;的产品；不懂业务，会做出&quot;做得出来、没人用&quot;的产品</td><td>第一~三章：信贷业务、流程、合规</td></tr><tr><td>风控</td><td>AI 模型越来越复杂，可解释性和合规压力同步增大</td><td>不懂系统，不知道风控规则怎么落地、模型结果怎么用；不懂业务，识别不了真正的风险点</td><td>第九~十一章：风控、反欺诈、模型评估</td></tr><tr><td>架构师</td><td>AI 组件引入新复杂度：模型服务、智能体编排、数据管道</td><td>不懂业务，架构会脱离实际场景；不懂技术，掌控不了AI 系统的黑盒和稳定性</td><td>第四~六章：架构、核心系统、核算引擎</td></tr><tr><td>CTO</td><td>AI 改变技术团队的能力结构和产出效率，人才模型要重写</td><td>不懂业务，做不出正确的技术投资决策；不懂技术，评估不了AI 的真实价值和风险</td><td>第八、十五章：技术组件、AI 工程化</td></tr><tr><td>CIO</td><td>AI 时代数字化转型加速，业务与 IT 对齐比以往更难</td><td>不懂业务，IT 撑不起业务战略；不懂技术，把握不了转型节奏和治理边界</td><td>第十二~十四章：互联网实践、传统转型、未来趋势</td></tr></tbody></table><p>这张表的核心判断是：AI 把每个角色的&quot;纯执行&quot;部分都压缩了，剩下的价值全在&quot;判断&quot;和&quot;整合&quot;上。对程序员和架构师来说，这个判断就是&quot;系统为什么这么做、能不能掌控它&quot;，这也是这本书的主线。其他角色的判断各有不同，但底层逻辑一样：AI 能给你信息，但做判断的人，必须同时懂业务和技术。</p><p>所以，AI 时代程序员要更懂商业逻辑。AI 把&quot;怎么做&quot;的门槛抹平了，剩下的分水岭，是&quot;为什么这么做&quot;，以及&quot;能不能掌控它&quot;。把商业逻辑和技术细节攥在手里，才能做出便宜、透明、真能解决问题的系统，而不是一个跑得通、却没人真正懂、也改不起的系统。</p><p>这本书，就是想把这两样东西拆开讲给你听。我建议你读三遍：第一遍跟业务线，看懂信贷的商业逻辑；第二遍跟技术线，把架构的地图摊开；第三遍跟风控与 AI 线，知道 AI 能帮到哪、帮不到哪。三遍走完，你手里就有一张完整的图。</p>',21);function h(q,i){const e=n("ExternalLinkIcon");return a(),r("div",null,[u,t("blockquote",null,[t("p",null,[d("公众号：侃西东　·　发布日期：2026-09-15　·　"),t("a",A,[d("微信原文"),p(e)])])]),s])}const l=o(c,[["render",h],["__file","003.html.vue"]]);export{l as default};
